query.query:
query QUERY($where: WorkcenterWhereInput, $orderBy: [WorkcenterOrderByInput!], $first: Int, $after: String, $creditAt: DateTime) {
 data : workcenter(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
 id
        code
        currentWorkcenterHistory {
          event {
            name
            eventType {
              color
            }
          }
          mode {
            name
            modeType {
              color
            }
          }
        }
        oees(
          where:{
            creditedAt:{_eq: $creditAt}
          }
        ){
          edges{
            node{
              oee
              availability
              performance
              quality
            }
          }
        }
      }
    }
  }
}
